PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "strategies" ("id" integer primary key autoincrement not null, "key" varchar not null, "name" varchar not null, "config" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "content_media" ("id" varchar not null, "content_item_id" varchar not null, "strategy_id" integer not null, "type" varchar check ("type" in ('image', 'video', 'graphic', 'carousel_slide', 'ad_creative')) not null, "url" varchar, "drive_file_id" varchar, "format" varchar check ("format" in ('4:5', '9:16', '1:1', '16:9', '1.91:1')), "status" varchar not null default 'briefing', "briefing" text, "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("content_item_id") references "content_items"("id") on delete cascade, foreign key("strategy_id") references "strategies"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "redaktionsplan_entries" ("id" integer primary key autoincrement not null, "strategy_id" integer not null, "content_item_id" varchar not null, "planned_date" date not null, "channel" varchar, "status" varchar not null default 'geplant', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("strategy_id") references "strategies"("id") on delete cascade, foreign key("content_item_id") references "content_items"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "content_strategies" ("id" integer primary key autoincrement not null, "strategy_id" integer not null, "key" varchar not null, "content" text not null, "version" integer not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("strategy_id") references "strategies"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "agent_logs" ("id" integer primary key autoincrement not null, "agent" varchar not null, "provider" varchar not null, "model" varchar not null, "input" text not null, "output" text not null, "status" varchar not null default 'success', "tokens_used" integer, "duration_ms" integer, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "monitoring_events" ("id" integer primary key autoincrement not null, "type" varchar not null, "status" varchar not null default 'success', "url" varchar, "query" varchar, "provider" varchar, "model" varchar, "credits" numeric, "input" text, "payload" text, "duration_ms" integer, "error" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "angles" ("id" varchar not null, "source_id" varchar, "strategy_id" integer not null, "batch_key" varchar, "angle" text not null, "icp" varchar, "pain_cluster" varchar, "statement_type" varchar, "funnel" varchar, "viscale_phase" varchar, "r_zielgruppe" integer, "r_viscale_fit" integer, "r_schaerfe" integer, "r_timing" integer, "ranking_score" integer, "ranking_rang" integer, "status" varchar not null default ('neu'), "created_at" datetime, "updated_at" datetime, "embedding" text, "score_reasoning" text, "duplicate_of_id" varchar, "similarity_score" float, foreign key("strategy_id") references strategies("id") on delete cascade on update no action, foreign key("source_id") references sources("id") on delete set null on update no action, foreign key("duplicate_of_id") references "angles"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "personas" ("id" integer primary key autoincrement not null, "strategy_id" varchar, "name" varchar not null, "role" varchar, "voice" text, "cadence" varchar, "active" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, "core_statements" text, "tonality" text, "positioning" varchar, "forbidden_words" text, "emoji_usage" varchar not null default ('none'), "perspective" varchar not null default ('ich'), foreign key("strategy_id") references strategies("id") on delete cascade on update no action);
CREATE TABLE IF NOT EXISTS "persona_strategy_map" ("id" integer primary key autoincrement not null, "persona_id" integer not null, "strategy_id" integer not null, "mapped_angles" text, "mapped_topics" text, "is_default" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("persona_id") references "personas"("id") on delete cascade, foreign key("strategy_id") references "strategies"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "persona_examples" ("id" integer primary key autoincrement not null, "persona_id" integer not null, "strategy_id" integer not null, "format" varchar not null, "content" text not null, "why_good" text, "active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("persona_id") references "personas"("id") on delete cascade, foreign key("strategy_id") references "strategies"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "workflow_runs" ("id" integer primary key autoincrement not null, "input" varchar, "output" text, "trace" text, "status" varchar not null default 'running', "duration_ms" integer, "exit_code" integer, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "content_kpis" ("id" integer primary key autoincrement not null, "strategy_id" integer not null, "content_item_id" varchar not null, "measured_at" date not null, "impressions" integer not null default '0', "reach" integer not null default '0', "clicks" integer not null default '0', "likes" integer not null default '0', "comments" integer not null default '0', "shares" integer not null default '0', "leads" integer not null default '0', "conversions" integer not null default '0', "revenue_eur" numeric, "open_rate" numeric, "click_rate" numeric, "primary_metric" varchar, "primary_value" numeric, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("strategy_id") references "strategies"("id") on delete cascade, foreign key("content_item_id") references "content_items"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "post_templates" ("id" integer primary key autoincrement not null, "name" varchar not null, "format" varchar not null, "description" varchar, "structure" text not null, "example" text, "best_for" text, "source" varchar check ("source" in ('builtin', 'custom', 'ai_generated')) not null default 'custom', "active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "funnel_stages" text);
CREATE TABLE IF NOT EXISTS "content_items" ("id" varchar not null, "strategy_id" integer not null, "angle_id" varchar, "type" varchar not null default ('idea'), "format" varchar not null default 'linkedin_post', "title" varchar, "content" text, "status" varchar not null default ('idee'), "owner" varchar, "live_date" date, "persona_id" varchar, "icp" varchar, "pain_cluster" varchar, "statement_type" varchar, "created_at" datetime, "updated_at" datetime, "variant_group_id" varchar, "variant_pattern" varchar, "quality_score" integer, "quality_comment" text, "quality_flags" text, foreign key("angle_id") references angles("id") on delete set null on update no action, foreign key("strategy_id") references strategies("id") on delete cascade on update no action, primary key ("id"));
CREATE TABLE IF NOT EXISTS "source_input_queue" ("id" integer primary key autoincrement not null, "source_id" varchar not null, "strategy_id" integer not null, "raw_content" text not null, "item_title" varchar, "item_url" varchar, "item_guid" varchar, "status" varchar not null default 'pending', "extracted_angles" text, "batch_key" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "sources" ("id" varchar not null, "strategy_id" integer not null, "title" varchar not null, "type" varchar check ("type" in ('pdf', 'url', 'interview', 'intern', 'research', 'rss', 'screenshot', 'community', 'video', 'audio')) not null, "visibility" varchar not null default 'intern', "file_ref" varchar, "batch_key" varchar, "created_at" datetime, "updated_at" datetime, "url" varchar, "monitor" tinyint(1) not null default '0', "frequency" varchar not null default 'weekly', "last_checked_at" datetime, "content_hash" varchar, "last_content_preview" varchar, "raw_content" text, "meta" text, foreign key("strategy_id") references "strategies"("id") on delete cascade, primary key ("id"));
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "strategies_key_unique" on "strategies" ("key");
CREATE INDEX "content_media_content_item_id_index" on "content_media" ("content_item_id");
CREATE INDEX "content_media_strategy_id_status_index" on "content_media" ("strategy_id", "status");
CREATE INDEX "content_media_type_index" on "content_media" ("type");
CREATE INDEX "redaktionsplan_entries_strategy_id_planned_date_index" on "redaktionsplan_entries" ("strategy_id", "planned_date");
CREATE INDEX "redaktionsplan_entries_strategy_id_status_index" on "redaktionsplan_entries" ("strategy_id", "status");
CREATE INDEX "redaktionsplan_entries_content_item_id_index" on "redaktionsplan_entries" ("content_item_id");
CREATE UNIQUE INDEX "content_strategies_strategy_id_key_unique" on "content_strategies" ("strategy_id", "key");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
CREATE INDEX "agent_logs_agent_created_at_index" on "agent_logs" ("agent", "created_at");
CREATE INDEX "agent_logs_created_at_index" on "agent_logs" ("created_at");
CREATE INDEX "monitoring_events_type_created_at_index" on "monitoring_events" ("type", "created_at");
CREATE INDEX "monitoring_events_status_created_at_index" on "monitoring_events" ("status", "created_at");
CREATE INDEX "angles_funnel_index" on "angles" ("funnel");
CREATE INDEX "angles_icp_index" on "angles" ("icp");
CREATE INDEX "angles_ranking_score_index" on "angles" ("ranking_score");
CREATE INDEX "angles_source_id_index" on "angles" ("source_id");
CREATE INDEX "angles_strategy_id_batch_key_index" on "angles" ("strategy_id", "batch_key");
CREATE INDEX "angles_strategy_id_status_index" on "angles" ("strategy_id", "status");
CREATE INDEX "personas_strategy_id_active_index" on "personas" ("strategy_id", "active");
CREATE UNIQUE INDEX "persona_strategy_map_persona_id_strategy_id_unique" on "persona_strategy_map" ("persona_id", "strategy_id");
CREATE INDEX "persona_examples_persona_id_format_active_index" on "persona_examples" ("persona_id", "format", "active");
CREATE INDEX "workflow_runs_created_at_index" on "workflow_runs" ("created_at");
CREATE INDEX "workflow_runs_status_index" on "workflow_runs" ("status");
CREATE UNIQUE INDEX "content_kpis_content_item_id_measured_at_unique" on "content_kpis" ("content_item_id", "measured_at");
CREATE INDEX "content_kpis_strategy_id_index" on "content_kpis" ("strategy_id");
CREATE INDEX "post_templates_format_index" on "post_templates" ("format");
CREATE INDEX "content_items_angle_id_index" on "content_items" ("angle_id");
CREATE INDEX "content_items_icp_index" on "content_items" ("icp");
CREATE INDEX "content_items_live_date_index" on "content_items" ("live_date");
CREATE INDEX "content_items_strategy_id_status_index" on "content_items" ("strategy_id", "status");
CREATE INDEX "content_items_strategy_id_type_index" on "content_items" ("strategy_id", "type");
CREATE INDEX "content_items_variant_group_id_index" on "content_items" ("variant_group_id");
CREATE INDEX "source_input_queue_source_id_status_index" on "source_input_queue" ("source_id", "status");
CREATE INDEX "source_input_queue_item_guid_index" on "source_input_queue" ("item_guid");
CREATE INDEX sources_strategy_id_index ON sources (strategy_id);
CREATE INDEX sources_type_index ON sources (type);
PRAGMA writable_schema=OFF;
COMMIT;
