INSERT INTO content_media VALUES('MED-464CAA','CNT-2A6070',1,'image',NULL,NULL,'1.91:1','briefing','{"prompt_hint":"Corporate style: IDENTIT\u00c4T\nviscale\u00ae \u2014 vollst\u00e4ndiges Vertriebs-Betriebssystem f\u00fcr KMU, HubSpot-basiert.\nUmfasst: CRM-Implementierung, Datenmigration, Schnittstellen-Anbindung, \nKI-Integration, Automatisierung, Coaching\/Sales-Enablement.\nKein CRM-Einf\u00fchrungsprojekt, kein reines Tool-Setup, kein Berater-Mandat.\nEin laufendes System mit nachweisbarem ROI \u2014 Technik + Methodik + Mensch zusammen.\n\nTONALIT\u00c4T\n- Sachlich-kompetent: Mechanismus erkl\u00e4ren, nicht versprechen\n- Methodisch-strukturiert, mehr System als Emotion\n- Vertrauensw\u00fcrdig, l\u00f6sungsorientiert\n- Weniger emotional als viminds (Mutterbrand), daf\u00fcr systematischer\n- Sie-Form in externen Dokumenten, Deutsch\n\nSPRACHREGELN\n- Konkrete Zahlen mit Kontext: \"von 3% auf 7%\" statt \"deutlich mehr\"\n- Spannungslogik: Problem benennen \u2192 Kosten des Problems \u2192 L\u00f6sung\/System\n- Kausalit\u00e4t statt Behauptung \u2014 belegbar, nicht behauptet\n- Kurze, klare S\u00e4tze \u2014 kein Schachtelsatz\n- Keine Ausrufezeichen\n\nVERBOTEN\n- Superlative (\"das beste CRM\", \"einzigartig\", \"revolution\u00e4r\")\n- Inspirational\/Coaching-Vokabular (\"Dein Vertrieb kann mehr\")\n- Feature-Auflistung statt Ergebnis\/Mechanismus\n- Buzzwords (\"skalieren\", \"digitale Transformation\")\n- \u00dcbertrieben emotional, aggressiv gegen namentlichen Wettbewerb\n- Fabrizierte ROI-Prozentzahlen\n\nSTATEMENT-TYPEN (situativ, gleiche Grundstimme)\nDirekt \u00b7 Drastisch \u00b7 Bedrohlich \u00b7 Humorvoll \u00b7 Sarkastisch \u00b7 Gain\n\nVISUELL\/FORMAL\n- Schreibweise immer \"viscale\u00ae\" lowercase, \u00ae nie weglassen\n- Nummern-Marker (01. 02. 03.) f\u00fcr Schritte\/Prozesse\n- Kern-Botschaft: \"Step-by-Step-Systematik mit allen n\u00f6tigen Bestandteilen f\u00fcr Strategie und Umsetzung\"\n\nABGRENZUNG ZU VIMINDS\nviminds = Agentur-Leistung allgemein, emotionaler\nviscale = Vertriebs-Betriebssystem (Tech + Methodik + Mensch), sachlicher, struktureller. Context: Eine saubere Wahrheit statt f\u00fcnf Insell\u00f6sungen \u2013 das Fundament, auf dem alles l\u00e4uft.. Target: B2B-3. No text overlay. Dark, muted tones.","generation_params":{"style":"Dunkel, reduziert, Brand Colors","aspect_ratio":"1.91:1","model":"flux-pro"},"notes":"Hero-Image f\u00fcr LinkedIn-Post. Optional \u2014 Text-only ist auch m\u00f6glich."}',0,'2026-09-15 11:55:00','2026-09-15 11:55:00');
