INSERT INTO agent_logs VALUES(39,'production','anthropic','anthropic/claude-sonnet-4-6',unistr('Schreibe einen linkedin_post für folgenden Content-Angle.\u000a\u000a## CONTENT-KERN\u000aANGLE (Kernaussage): Vertrieb hängt oft an Personen statt an Prozessen – wir schaffen ein System, das unabhängig von Einzelpersonen funktioniert.\u000aICP: B2B-1\u000aPain-Cluster: E3-02 · Vertrieb hängt an Personen\u000aSTATEMENT-TYP (Sarkastisch): Formuliere mit spitzer, leis ironischer Zuspitzung — ohne giftig zu werden.\u000aPATTERN: Mistake Post — Die N häufigsten Fehler bei X\u000aStruktur (zwingend einhalten, jeder Punkt = eigener Absatz): Fehler 1 + Folge → Fehler 2 + Folge → Fehler 3 + Folge → Wie man es richtig macht → Soft CTA\u000aBeispiel (nur als Stil-Referenz, NICHT kopieren): "3 Fehler bei der HubSpot-Property-Hygiene: 1. Pflichtfelder nicht gesetzt. 2. Keine Pipeline-Stages definiert. 3. Datenqualität nie geprüft. Die Lösung: Einmal Setup, wöchentliches Review."\u000a\u000a## STIL-LAYER (Persona)\u000a\u000a## ZIEL-LAYER (Kanal/Format)\u000aKANAL-REGELN:\u000a- Länge: 120-220 Wörter\u000a- Hook (Zeile 1): max 12 Wörter, provokante These\u000a- Aufbau: Hook (Zeile 1, max 12 Wörter, provokante These) → Kontext/Problem (2-3 Sätze) → Mechanismus/Beleg (3-5 Sätze, konkreter Nutzen) → Konsequenz für den Leser (1-2 Sätze) → Soft CTA (1 Satz)\u000a- CTA: Soft CTA — Frage oder Einladung zum Austausch, kein harter Verkauf\u000aHashtags am Ende: #viscale #Vertriebssystem #HubSpot #Mittelstand\u000a\u000aGib NUR den Content-Text aus.\u000a'),unistr('3 Fehler, die deinen Vertrieb von einer Person abhängig machen.\u000a\u000a**Fehler 1: Kein dokumentierter Prozess.**\u000aWenn nur "der Thomas" weiß, wie Deals laufen, läuft der Vertrieb — solange Thomas da ist. Kündigt Thomas, kündigt der Prozess mit.\u000a\u000a**Fehler 2: Wissen lebt in Köpfen, nicht im CRM.**\u000aGesprächshistorien, Einwände, Entscheidungslogik — alles mental gespeichert. Das nächste Gespräch beginnt bei null, weil niemand sonst Zugriff auf das hat, was Thomas weiß.\u000a\u000a**Fehler 3: Forecasts basieren auf Bauchgefühl statt Daten.**\u000a"Thomas sagt, der Deal kommt" ist kein Forecast. Es ist eine Hoffnung mit Termin.\u000a\u000aWie man es richtig macht: Vertrieb wird zum System, wenn Prozesse, Informationen und Prognosen im CRM abgebildet sind — nicht im Kopf einer Person. HubSpot kann das abbilden, wenn es sauber aufgesetzt ist. Dann ist Thomas wertvoll, aber nicht unersetzbar.\u000a\u000aWie sieht das bei deinem Team aus — läuft der Vertrieb auch dann, wenn jemand ausfällt?\u000a\u000a#viscale #Vertriebssystem #HubSpot #Mittelstand'),'success',2017,9363,'2026-09-10 14:54:44','2026-09-10 14:54:44');
