INSERT INTO agent_logs VALUES(52,'angle','anthropic','anthropic/claude-sonnet-4-6',unistr('Extrahiere Angles aus diesem Text (Angles auf Deutsch):\u000a\u000a---\u000aHubSpot flexible seats and credits pricing. Companies waste budget on unused licenses. Automation must be built cleanly from the start, otherwise you digitize chaos. Many teams buy tools before defining their sales process.\u000a---\u000a'),unistr('```json\u000a[\u000a  {\u000a    "angle": "Viele Unternehmen verbrennen Budget für ungenutzte Software-Lizenzen, die niemand braucht.",\u000a    "icp": "B2B-2",\u000a    "pain_cluster": "E3-05",\u000a    "statement_type": "Drastisch"\u000a  },\u000a  {\u000a    "angle": "Wer Automatisierung auf einem chaotischen Prozess aufbaut, digitalisiert nur das Chaos.",\u000a    "icp": "",\u000a    "pain_cluster": "E1-02",\u000a    "statement_type": "Bedrohlich"\u000a  },\u000a  {\u000a    "angle": "Die meisten Teams kaufen Tools, bevor sie ihren Vertriebsprozess überhaupt definiert haben.",\u000a    "icp": "B2B-2",\u000a    "pain_cluster": "E3-05",\u000a    "statement_type": "Direkt"\u000a  },\u000a  {\u000a    "angle": "Flexible Lizenzmodelle wie bei HubSpot klingen gut – aber nur wer seinen Bedarf kennt, spart wirklich.",\u000a    "icp": "B2B-2",\u000a    "pain_cluster": "E3-05",\u000a    "statement_type": "Mechanismus"\u000a  }\u000a]\u000a```'),'success',1027,5340,'2026-09-15 06:40:26','2026-09-15 06:40:26');
INSERT INTO agent_logs VALUES(53,'angle','anthropic','anthropic/claude-sonnet-4-6',unistr('Extrahiere Angles aus diesem Text (Angles auf Deutsch):\u000a\u000a---\u000aHubSpot flexible seats pricing. Companies waste budget on unused licenses. Automation must be built cleanly from the start. Many teams buy tools before defining their sales process. Forecast accuracy improves with data hygiene.\u000a---\u000a'),unistr('```json\u000a[\u000a  {\u000a    "angle": "Viele Teams kaufen Tools, bevor sie ihren Vertriebsprozess definiert haben – und zahlen dann doppelt.",\u000a    "icp": "B2B-2",\u000a    "pain_cluster": "E3-05",\u000a    "statement_type": "Direkt"\u000a  },\u000a  {\u000a    "angle": "Forecast-Genauigkeit ist kein Glück – sie ist das direkte Ergebnis sauberer Datenhygiene.",\u000a    "icp": "B2B-1",\u000a    "pain_cluster": "E3-01",\u000a    "statement_type": "Mechanismus"\u000a  },\u000a  {\u000a    "angle": "Unternehmen verbrennen Budget für Lizenzen, die niemand nutzt – weil Prozesse fehlen, nicht Tools.",\u000a    "icp": "B2B-2",\u000a    "pain_cluster": "E3-05",\u000a    "statement_type": "Drastisch"\u000a  },\u000a  {\u000a    "angle": "Automatisierung funktioniert nur, wenn sie von Anfang an sauber aufgebaut wird – nachträglich flicken kostet mehr als neu starten.",\u000a    "icp": "",\u000a    "pain_cluster": "E3-06",\u000a    "statement_type": "Bedrohlich"\u000a  }\u000a]\u000a```'),'success',1042,5831,'2026-09-15 06:41:06','2026-09-15 06:41:06');
INSERT INTO agent_logs VALUES(54,'angle','anthropic','anthropic/claude-sonnet-4-6',unistr('Extrahiere Angles aus diesem Text (Angles auf Deutsch):\u000a\u000a---\u000aWith HubSpot Credits, you only pay for what you use, giving you control over your budget and scaling needs. Forecast accuracy improves with clean data hygiene. Leads often slip through without follow-up.\u000a---\u000a'),unistr('```json\u000a[\u000a  {\u000a    "angle": "Wer nur zahlt, was er nutzt, behält die Kontrolle über Budget und Wachstum – statt in starren Lizenzmodellen zu versinken.",\u000a    "icp": "",\u000a    "pain_cluster": "E3-05",\u000a    "statement_type": "Gain"\u000a  },\u000a  {\u000a    "angle": "Saubere Datenhygiene ist keine Fleißaufgabe – sie ist die Grundlage für Forecasts, denen du tatsächlich vertrauen kannst.",\u000a    "icp": "",\u000a    "pain_cluster": "E3-01",\u000a    "statement_type": "Mechanismus"\u000a  },\u000a  {\u000a    "angle": "Leads verschwinden nicht – sie werden nur nicht nachgefasst. Der Unterschied kostet Umsatz.",\u000a    "icp": "",\u000a    "pain_cluster": "E3-03",\u000a    "statement_type": "Bedrohlich"\u000a  }\u000a]\u000a```'),'success',959,5056,'2026-09-15 06:58:50','2026-09-15 06:58:50');
INSERT INTO agent_logs VALUES(55,'angle','anthropic','anthropic/claude-sonnet-4-6',unistr('Extrahiere Angles aus diesem Text (Angles auf Deutsch):\u000a\u000a---\u000aAggregierte Angle-Übersicht — bereinigt, dedupliziert\u000a\u000aBatch: HubSpot April 2026 (5)\u000a\u000aCall-Auto-Sync ins CRM — manuelle Pflege entfällt\u000aKI extrahiert Budget/Timing-Signale aus Calls & Mails\u000aMarkensichtbarkeit in ChatGPT/Perplexity — die meisten KMU bei null\u000aDuplikate-Score — Kundenvertrauen statt nur Speicherplatz\u000aKI-Feature-Release-Tempo April > letzte 6 Monate\u000a\u000aBatch: Agent Era (5)\u000a\u000aDatenqualität ist Umsatzthema, nicht IT-Thema\u000aBezahlung für erledigte Arbeit statt Software\u000aPartner bauen branchenspezifische Agenten — Prozesswissen zählt\u000aDeal-Risiko-Scores aus 280.000 Kunden — Eigenbau-CRM hält nicht mit\u000a\u000aBatch: Cixon-Wettbewerb (5 aktiv, 1 verwendet — Duplikat zu Agent Era Punkt 1)\u000a\u000aPartner zeigen Tool-Funktion, nicht was danach passiert\u000aCRM bremst durch fehlende Kostendefinition pro Vertriebsschritt\u000a200+ Partner in DE — Differenzierung über System statt Tool\u000aAgent auf schlechten Daten (Dublette, bereits „verwendet")\u000a7 Jahre / 100 Projekte — Zeit für Evaluierung als Learning\u000a\u000aNeuer Vertriebler performt nicht → fehlendes System, nicht fehlender Mensch\u000a\u000aBatch: Pricing/Neues Modell (7, aus D-1 bis D-7)\u000a\u000aKein Seat-Minimum — Einstieg auch für kleine Teams\u000aGTM Seat vereint alle Rollen — kein Lizenz-Jonglieren\u000aCredits = nutzungsbasiert, fair für kleine Teams\u000aEin System statt Hub-Silos\u000aOps Seat 9€/Monat — Einstiegshürde gefallen\u000a3 Kaufentscheidungen statt 70+ — Partner-Wert verschiebt sich zu System-Aufbau\u000a\u000aNeu identifiziert, nicht dupliziert (aus Partner-PDF, thematisch neu)\u000a\u000aTCO über 3 Jahre als CFO-Argument (Rechenbeispiel-Format)\u000aCross-Selling durch Plattform-Verweildauer statt neuem Pitch\u000aCapacity Packs als 