INSERT INTO agent_logs VALUES(85,'production','anthropic','anthropic/claude-sonnet-4-6',unistr('Schreibe einen linkedin_post für folgenden Content-Angle.\u000a\u000a## CONTENT-KERN\u000aANGLE (Kernaussage): Durchgängige Systeme machen Abschlüsse steuerbar und nicht zur Kopfsache.\u000aICP: B2B-1\u000aPain-Cluster: E3-02 · Vertrieb hängt an Personen\u000aSTATEMENT-TYP (Direkt): Formuliere sachlich und direkt — eine klare, unmissverständliche Aussage ohne Drama.\u000aPATTERN: Storytelling Post — Persönliche Geschichte mit Lerneffekt. Emotionaler als andere Formate, baut Vertrauen auf. Ideal für warme Zielgruppen (MoFu).\u000aStruktur (die inhaltliche Dramaturgie — führe die Gedanken in dieser Reihenfolge als zusammenhängenden, fließenden Text):\u000aHook (emotional / neugierig)\u000aAusgangssituation / Problem\u000aWendepunkt (Erkenntnis)\u000aLösung / Learnings\u000aCTA\u000aWICHTIG: Die obigen Struktur-Begriffe sind nur interne Gedankenstützen für dich. Schreibe sie NICHT als Überschriften, Zwischentitel oder Labels in den Text. Der Leser soll eine durchgehende, natürliche Erzählung lesen — keine Gliederung mit Stichwort-Headern.\u000aBeispiel (nur als Stil-Referenz, NICHT kopieren): "Letzte Woche saß ich mit einem CEO zusammen, der nicht wusste, wo seine Deals gerade stehen. Wir haben in 2 Stunden seine Pipeline aufgeräumt. Ergebnis: 30% mehr Sichtbarkeit."\u000a\u000a## STIL-LAYER (Persona)\u000aPersona: Tim Ratig (Gründer viminds/viscale®)\u000aSprachstil: Sachlich-kompetenter B2B-Vertriebsexperte, kein Coach, kein Influencer\u000a\u000aSTIMME\u000a- Ich-Stimme des GF — eigene Beobachtung, nicht Marketing-Abteilung\u000a- Mechanismus erklären, nicht Versprechen machen\u000a- Konkrete Zahlen mit Kontext: "von 3% auf 7%" statt "deutlich mehr"\u000a- Spannungsaufbau: Problem → Kosten des Problems → Lösung\u000a- Kurze Zeilen, kein Fließtext, Weißraum statt Emojis (max. 1-2)\u000aErzählperspektive: ich\u000aEmoji-Nutzung: keine Emojis verwenden\u000aBRAND VOICE (Strategie):\u000a- Persönlichkeit: IDENTITÄT\u000aviscale® — vollständiges Vertriebs-Betriebssystem für KMU, HubSpot-basiert.\u000aUmfasst: CRM-Implementierung, Datenmigration, Schnittstellen-Anbindung, \u000aKI-Integration, Automatisierung, Coaching/Sales-Enableme'),unistr('Wenn ein Abschluss davon abhängt, wer gerade im Büro ist, fehlt ein System.\u000a\u000aIch habe das in einem Beratungsgespräch vor einigen Monaten wieder gesehen: Ein Vertriebsleiter konnte mir nicht sagen, welche Deals seiner drei Außendienstler gerade in welcher Phase stecken, weil jeder seinen eigenen Rhythmus hatte und die Informationen nirgendwo zusammenliefen. Kein Datenproblem, sondern ein Strukturproblem.\u000a\u000aWas dort fehlte, war ein durchgehender Prozess, der Angebote, Kontakte und Gesprächsstände so abbildet, dass jede Führungskraft zu jedem Zeitpunkt nachvollziehen kann, was als Nächstes passiert und warum. Sobald das in HubSpot abgebildet war, sank die Abhängigkeit von einzelnen Personen spürbar, weil das System die Logik trug und nicht mehr der Kopf des jeweiligen Mitarbeiters.\u000a\u000aVertrieb, der an Personen hängt, ist kein Zeichen von starkem Team, sondern ein Hinweis darauf, dass das System noch nicht steht. Wenn eine Person ausfällt und drei Deals damit ins Stocken geraten, ist das kein Pech, sondern ein Konstruktionsfehler.\u000a\u000aWelche Deals in eurem Vertrieb würden heute stillstehen, wenn eine Person morgen ausfällt?\u000a\u000a#viscale #Vertriebssystem #HubSpot #Mittelstand'),'success',5055,11257,'2026-09-15 12:53:49','2026-09-15 12:53:49');
