INSERT INTO angles VALUES('ANG-478234',NULL,1,NULL,'Test-Variante','B2B-1',NULL,NULL,NULL,NULL,1,1,1,1,4,21,'bewertet','2026-09-01 11:26:44','2026-09-08 09:20:06',NULL,'Der Angle ''Test-Variante'' ist sehr generisch und trifft keine spezifische Zielgruppe oder Strategie. Er ist weder provokativ noch aktuell und passt nicht zu den verfügbaren Clustern.',NULL,NULL);
INSERT INTO angles VALUES('ANG-AD19D8',NULL,1,'quick-20260901','Systemgetrieben Vertrieb & Service ohne Personenabhängigkeit − Angebotszeit CPQ direkt in HubSpot Auto-Support Breeze AI klassifiziert & antwortet Industrie-IT Ausgangslage Kein zentrales CRM.','B2B-3','E3-02 · Vertrieb hängt an Personen','Direkt',NULL,NULL,3,3,2,3,11,1,'approved','2026-09-01 19:30:02','2026-09-08 09:20:08',NULL,'Der Angle trifft punktgenau den ICP B2B-3, da er sich auf systemgetriebenen Vertrieb und Service ohne Personenabhängigkeit fokussiert, was für Unternehmen im B2B-Bereich relevant ist. Die Strategie passt perfekt, da der Angle innovative Technologien wie CPQ und KI-gestützten Support anspricht. Der Angle ist pointiert, aber nicht extrem provokativ, und die Themen sind hochaktuell und im Trend.',NULL,NULL);
INSERT INTO angles VALUES('ANG-AD272F',NULL,1,'quick-20260901','Mehr qualifizierte Anfragen Steuerbarer Vertrieb Daten in einem System Wachstumsgespräch buchen In 30 Min unverbindlich dein erster Schritt zu Klarheit Wachstum · Dashboard live Qualifizierte Anfragen+180 % Pipeline-Wertsteigend Conversion Rate+32 % 250+Projekte im DACH-Raum Vertrauen von über 250 Mittelständlern im DACH-Raum Warum Wachstum stockt ## Verpuffte Kampagnen, zäher Vertrieb, stockender Umsatz.','B2B-2','E3-01 · Blindflug im Forecast','Direkt',NULL,NULL,3,2,2,2,9,9,'bewertet','2026-09-01 19:30:02','2026-09-08 09:20:32',NULL,'Der Angle spricht gezielt mittelständische Unternehmen im B2B-Bereich an, die mit Vertriebs- und Umsatzproblemen kämpfen, was den ICP B2B-2 punktgenau trifft. Die Strategie passt gut, da der Fokus auf Wachstum und Effizienz liegt, jedoch könnte die Verbindung zu ''Blindflug im Forecast'' klarer sein. Der Angle ist pointiert, aber nicht extrem provokativ, und das Thema ist aktuell, aber nicht unbedingt trendführend.',NULL,NULL);
INSERT INTO angles VALUES('ANG-37900B',NULL,1,'quick-20260901','Eine saubere Wahrheit statt fünf Insellösungen – das Fundament, auf dem alles läuft.','B2B-3','E3-06 · Datenchaos & fehlende Datenhygiene','Direkt',NULL,NULL,3,3,2,2,10,2,'approved','2026-09-01 19:31:31','2026-09-08 09:20:14',NULL,'Der Angle trifft punktgenau den ICP B2B-3, da er sich auf Datenchaos und Datenhygiene fokussiert, was für Unternehmen relevant ist. Er passt perfekt zur Strategie, da er eine klare Lösung für ein spezifisches Problem bietet. Der Angle ist pointiert, aber nicht extrem provokativ. Das Thema ist aktuell, da Datenmanagement in Unternehmen immer wichtiger wird.',NULL,NULL);
INSERT INTO angles VALUES('ANG-37962D',NULL,1,'quick-20260901','Genau daran scheitern die meisten CRM-Projekte – deshalb bauen wir Prozesse, die deinem Team die Arbeit erleichtern statt zusätzliche Pflicht zu sein.','B2B-3','E3-01 · Blindflug im Forecast','Direkt',NULL,NULL,3,2,2,2,9,10,'bewertet','2026-09-01 19:31:31','2026-09-08 09:20:32',NULL,'Der Angle trifft punktgenau die B2B-3 Zielgruppe, da er sich auf CRM-Projekte konzentriert, die in der Regel für größere Unternehmen relevant sind. Er passt gut zur Strategie, da er Prozesse zur Erleichterung der Arbeit hervorhebt, ist jedoch nicht perfekt auf den Cluster ''Blindflug im Forecast'' abgestimmt. Der Angle ist pointiert, da er ein häufiges Problem anspricht, und aktuell, da CRM-Projekte weiterhin ein relevantes Thema sind.',NULL,NULL);
INSERT INTO angles VALUES('ANG-379B64',NULL,1,'quick-20260901','Ziel: eine einzige Wahrheit statt fünf Insellösungen.','B2B-1','E3-01 · Blindflug im Forecast','Direkt',NULL,NULL,3,2,2,2,9,11,'bewertet','2026-09-01 19:31:31','2026-09-08 09:20:32',NULL,'Der Angle trifft punktgenau auf B2B-1, da Unternehmen oft mit Insellösungen kämpfen. Er passt gut zur Strategie, da er die Notwendigkeit einer einheitlichen Lösung betont. Der Angle ist pointiert, aber nicht extrem provokativ. Das Thema ist aktuell, da viele Unternehmen nach integrierten Lösungen suchen.',NULL,NULL);
INSERT INTO angles VALUES('ANG-379FA4',NULL,1,'quick-20260901','Das ist kein Fleiß-, sondern ein Systemproblem – und genau das lösen wir mit einem durchgängigen System.','B2B-1','E3-01 · Blindflug im Forecast','Direkt',NULL,NULL,2,2,2,2,8,19,'bewertet','2026-09-01 19:31:31','2026-09-08 09:20:32',NULL,'Der Angle spricht ein Systemproblem an, das für B2B-1 relevant ist, jedoch nicht punktgenau. Er passt zur Strategie, da er ein durchgängiges System als Lösung anbietet. Die Formulierung ist pointiert, aber nicht extrem provokativ. Das Thema ist aktuell, da viele Unternehmen nach Effizienzsteigerungen suchen.',NULL,NULL);
INSERT INTO angles VALUES('ANG-37A368',NULL,1,'quick-20260901','Sichtbarkeit und ein konstanter Strom qualifizierter Anfragen – statt Zufallsleads.','B2B-1','E3-03 · Leads versickern unbemerkt','Direkt',NULL,NULL,3,2,2,2,9,12,'bewertet','2026-09-01 19:31:31','2026-09-08 09:20:32',NULL,'Der Angle trifft punktgenau den B2B-1 ICP, da er sich auf qualifizierte Anfragen und nicht auf Zufallsleads konzentriert, was für B2B-Unternehmen entscheidend ist. Der Fit zur Strategie ist passend, da der Fokus auf Sichtbarkeit und qualifizierten Anfragen liegt. Der Angle ist pointiert, da er den Unterschied zwischen qualifizierten Anfragen und Zufallsleads betont. Das Thema ist aktuell, da Unternehmen ständig nach besseren Lead-Qualifizierungsstrategien suchen.',NULL,NULL);
INSERT INTO angles VALUES('ANG-E0A602',NULL,1,'quick-20260901','Vertrieb hängt oft an Personen statt an Prozessen – wir schaffen ein System, das unabhängig von Einzelpersonen funktioniert.','B2B-1','E3-02 · Vertrieb hängt an Personen','Drastisch',NULL,NULL,3,3,2,2,10,3,'approved','2026-09-01 21:10:06','2026-09-08 09:20:24',NULL,'Der Angle trifft punktgenau auf den ICP B2B-1 zu, da er ein häufiges Problem im B2B-Vertrieb adressiert. Er passt perfekt zur Strategie, da er ein spezifisches Problem im Vertrieb anspricht. Der Angle ist pointiert, aber nicht extrem provokativ. Das Thema ist aktuell, da viele Unternehmen nach effizienteren Vertriebsprozessen suchen.',NULL,NULL);
INSERT INTO angles VALUES('ANG-EB704C',NULL,1,'quick-20260901','Ein sauberes CRM-System ist das Fundament für planbares Wachstum und effiziente Prozesse.','B2B-1','E3-06 · Datenchaos & fehlende Datenhygiene','Vision',NULL,NULL,3,3,2,2,10,4,'approved','2026-09-01 21:10:06','2026-09-08 09:20:26',NULL,'Der Angle trifft punktgenau den ICP B2B-1, da ein sauberes CRM-System für B2B-Unternehmen essenziell ist. Er passt perfekt zur Strategie, da er die Bedeutung von Datenhygiene betont. Der Angle ist pointiert, aber nicht provokativ. Das Thema ist aktuell, da Datenmanagement in der digitalen Transformation wichtig bleibt.',NULL,NULL);
INSERT INTO angles VALUES('ANG-F60430',NULL,1,'quick-20260901','Marketing, Vertrieb und CRM müssen Hand in Hand gehen, um aus Nachfrage steuerbare Abschlüsse zu machen.','B2B-1',NULL,'Mechanismus',NULL,NULL,3,2,2,2,9,13,'bewertet','2026-09-01 21:10:07','2026-09-08 09:20:32',NULL,'Der Angle trifft punktgenau den B2B-1 ICP, da er die Integration von Marketing, Vertrieb und CRM anspricht, was für B2B-Unternehmen essenziell ist. Er passt gut zur Strategie, ist pointiert, aber nicht extrem provokativ, und behandelt ein aktuelles Thema im Bereich der Unternehmensoptimierung.',NULL,NULL);
INSERT INTO angles VALUES('ANG-FB938D',NULL,1,'quick-20260901','Viele Unternehmen kämpfen mit Insellösungen – wir integrieren alles in ein zentrales System für klare Prozesse.','B2B-1','E3-06 · Datenchaos & fehlende Datenhygiene','Drastisch',NULL,NULL,3,2,2,2,9,14,'bewertet','2026-09-01 21:10:07','2026-09-08 09:20:32',NULL,'Der Angle trifft punktgenau auf B2B-Unternehmen, die mit Insellösungen kämpfen. Er passt gut zur Strategie, da er Integration und Prozessklarheit betont. Die Formulierung ist pointiert, aber nicht scharf. Das Thema ist aktuell, da viele Unternehmen nach Effizienzsteigerungen suchen.',NULL,NULL);
INSERT INTO angles VALUES('ANG-029C3A',NULL,1,'quick-20260901','Ein strukturiertes System macht Wachstum planbar und wiederholbar, statt auf Zufall zu setzen.','B2B-1','E3-05 · Wachstum wird teurer statt effizienter','Vision',NULL,NULL,3,3,2,2,10,5,'approved','2026-09-01 21:10:08','2026-09-08 09:20:32',NULL,'Der Angle trifft punktgenau auf B2B-1, da er sich auf planbares Wachstum konzentriert, was für Unternehmen im B2B-Bereich entscheidend ist. Er passt perfekt zur Strategie, da er Effizienz im Wachstum betont. Der Angle ist pointiert, aber nicht extrem provokativ, und das Thema ist aktuell relevant, da viele Unternehmen nach strukturierten Wachstumsstrategien suchen.',NULL,NULL);
