INSERT INTO angles VALUES('ANG-4C33C8','SRC-9881D9',1,'quick-20260915','60 % aller Suchanfragen enden heute ohne einen einzigen Klick. Wer nicht in KI-Antworten auftaucht, existiert für den Käufer schlicht nicht.','B2B-1','E1-02 · KI-Druck ohne Fundament','Drastisch','ToFu',NULL,2,3,3,3,11,1,'approved','2026-09-15 12:55:32','2026-09-15 12:55:36',NULL,'Der Angle spricht B2B-Unternehmen an, die sich mit der Sichtbarkeit in KI-generierten Antworten auseinandersetzen müssen, was relevant ist, aber nicht ausschließlich für B2B-1. Der Angle passt perfekt zur Strategie, da er den Druck durch KI thematisiert. Er ist scharf formuliert und greift ein aktuelles Trendthema auf.',NULL,NULL);
INSERT INTO angles VALUES('ANG-960AEA','SRC-9881D9',1,'quick-20260915','Wenn eine KI dich empfiehlt, gewinnst du den Deal, bevor der Wettbewerber auch nur einen Klick bekommt.','B2B-1','E1-02 · KI-Druck ohne Fundament','Gain','ToFu',NULL,2,2,3,3,10,2,'approved','2026-09-15 12:55:37','2026-09-15 12:55:41',NULL,'Der Angle spricht B2B-Kunden an, die an KI-gestützten Lösungen interessiert sind, trifft aber nicht punktgenau den spezifischen ICP B2B-1. Der Fit zur Strategie ist passend, da KI-Druck thematisiert wird, aber nicht perfekt. Der Angle ist scharf formuliert und nutzt den aktuellen Trend der KI-Implementierung im Vertrieb.',NULL,NULL);
INSERT INTO angles VALUES('ANG-E1CEFD','SRC-9881D9',1,'quick-20260915','66 % der Nutzer handeln auf Basis von KI-Antworten — ohne die Quelle je zu prüfen. Sichtbarkeit in LLMs ist kein Vorteil mehr, sondern Grundvoraussetzung.','B2B-1','E1-02 · KI-Druck ohne Fundament','Bedrohlich','ToFu',NULL,2,2,3,3,10,3,'approved','2026-09-15 12:55:42','2026-09-15 12:55:44',NULL,'Der Angle spricht B2B-Unternehmen an, die sich mit KI-Integration beschäftigen, trifft aber nicht punktgenau den spezifischen ICP B2B-1. Der Angle passt zur Strategie, da er die Notwendigkeit der Sichtbarkeit in LLMs betont, ist jedoch nicht perfekt abgestimmt. Der provokative Ton und die Aktualität des Themas KI machen den Angle scharf und trendbezogen.',NULL,NULL);
INSERT INTO angles VALUES('ANG-160111','SRC-9881D9',1,'quick-20260915','AEO ist das neue SEO. Wer jetzt noch optimiert als wäre es 2019, verliert Käufer bevor das erste Gespräch stattfindet.','B2B-1','E3-01 · Blindflug im Forecast','Direkt','ToFu',NULL,2,2,3,3,10,4,'approved','2026-09-15 12:55:45','2026-09-15 12:55:49',NULL,'Der Angle spricht B2B-Unternehmen an, die sich mit digitalen Marketingstrategien beschäftigen, was relevant ist, aber nicht punktgenau auf B2B-1 zugeschnitten. Der Vergleich von AEO mit SEO ist provokativ und aktuell, da es auf neue Trends im digitalen Marketing hinweist.',NULL,NULL);
INSERT INTO angles VALUES('ANG-622400','SRC-9881D9',1,'quick-20260915','40 % der Konsumenten vertrauen KI-Suchergebnissen mehr als klassischen Google-Treffern. Deine Website-Strategie sollte das längst wissen.','B2B-1','E1-02 · KI-Druck ohne Fundament','Direkt','ToFu',NULL,2,2,2,3,9,5,'bewertet','2026-09-15 12:55:50','2026-09-15 12:55:52',NULL,'Der Angle spricht B2B-Unternehmen an, die sich mit KI und Suchmaschinenoptimierung beschäftigen, was relevant, aber nicht punktgenau für B2B-1 ist. Die Strategie passt, da KI ein aktuelles Thema ist, jedoch nicht perfekt. Der Angle ist pointiert, aber nicht extrem provokativ. Das Thema ist sehr aktuell und trendbezogen.',NULL,NULL);
INSERT INTO personas VALUES(8,'1','Tim Ratig','Gründer viminds/viscale®',unistr('Sachlich-kompetenter B2B-Vertriebsexperte, kein Coach, kein Influencer\u000a\u000aSTIMME\u000a- Ich-Stimme des GF — eigene Beobachtung, nicht Marketing-Abteilung\u000a- Mechanismus erklären, nicht Versprechen machen\u000a- Konkrete Zahlen mit Kontext: "von 3% auf 7%" statt "deutlich mehr"\u000a- Spannungsaufbau: Problem → Kosten des Problems → Lösung\u000a- Kurze Zeilen, kein Fließtext, Weißraum statt Emojis (max. 1-2)'),'weekly',1,'2026-09-15 12:49:52','2026-09-15 12:50:31','[]','{"style":"direkt","do":["Ich-Stimme des GF","Mechanismus erkl\u00e4ren","Konkrete Zahlen mit Kontext","Spannungsaufbau","Kurze Zeilen"],"dont":["Ausrufezeichen","Superlative","Inspirational-Talk","Feature-Beschreibung","Generische Abschlussfragen","Aggressiv gegen Wettbewerb"]}',NULL,'[]','none','ich');
INSERT INTO persona_strategy_map VALUES(6,8,1,NULL,NULL,1,'2026-09-15 12:49:52','2026-09-15 12:49:52');
INSERT INTO persona_strategy_map VALUES(7,8,3,'[]','[]',0,'2026-09-24 08:28:28','2026-09-24 08:28:28');
INSERT INTO post_templates VALUES(1,'Contrarian Take','linkedin_post','Gegen den Mainstream — alle sagen X, Realität ist Y. Provoziert, weckt Neugier. Gut für kalte Zielgruppen, die dich noch nicht kennen.',unistr('These gegen den Mainstream (max 8 Wörter)\u000aWarum der Mainstream irrt\u000aBeleg / Mechanismus\u000aWas das für den Leser heißt\u000aSoft CTA'),'CRM-Automatisierung macht euren Vertrieb schlechter. Weil sie Prozesse optimiert, die gar nicht funktionieren. Erst Struktur, dann Automatisierung. Sonst digitalisiert ihr nur Chaos.','["B2B-2","B2B-3"]','builtin',1,'2026-09-14 10:34:20','2026-09-14 10:34:20','["tofu"]');
INSERT INTO post_templates VALUES(2,'Data Drop','linkedin_post','Überraschende Zahl + Einordnung. Stoppt den Scroll-Fluss sofort. Ideal für ToFu, wenn du mit einem Fakt überraschen kannst.',unistr('Überraschende Zahl / Fakt\u000aWarum das überrascht\u000aMechanismus dahinter\u000aKonsequenz für den Leser\u000aSoft CTA'),'73% der Forecasts liegen daneben. Nicht wegen schlechter Sales-Leute, sondern wegen fehlender Datenhygiene. Wer seine Pipeline nicht pflegt, steuert blind.','["B2B-1","B2B-2"]','builtin',1,'2026-09-14 10:34:20','2026-09-14 10:34:20','["tofu"]');
INSERT INTO post_templates VALUES(3,'Mistake Post','linkedin_post','Die N häufigsten Fehler bei X. Zeigt Schmerz + Mechanismus. Ideal für MoFu: Zielgruppe kennt das Problem schon, sucht Lösung.',unistr('Fehler 1 + Folge\u000aFehler 2 + Folge\u000aFehler 3 + Folge\u000aWie man es richtig macht\u000aSoft CTA'),'3 Fehler bei der HubSpot-Property-Hygiene: 1. Pflichtfelder nicht gesetzt. 2. Keine Pipeline-Stages definiert. 3. Datenqualität nie geprüft. Die Lösung: Einmal Setup, wöchentliches Review.','["B2B-3","B2B-1"]','builtin',1,'2026-09-14 10:34:20','2026-09-14 10:34:20','["mofu"]');
INSERT INTO post_templates VALUES(4,'Framework / Modell','linkedin_post','Eigenes Denkmodell teilen. Baut Autorität auf, zeigt Methodik. Gut für MoFu-Zielgruppen, die dich schon kennen und Tiefe suchen.',unistr('Problem-Skizze\u000aModell-Übersicht (3 Stufen)\u000aStufe 1 …\u000aStufe 2 …\u000aStufe 3 …\u000aErgebnis bei Anwendung\u000aSoft CTA'),'Unser 3-Stufen-Modell für Datenhygiene: 1. Audit — was ist der Ist-Zustand? 2. Struktur — welche Felder brauchen wir wirklich? 3. Rhythmus — wer prüft wann? Ergebnis: Forecast-Sicherheit in 4 Wochen.','["B2B-1","B2B-2"]','builtin',1,'2026-09-14 10:34:20','2026-09-14 10:34:20','["mofu"]');
INSERT INTO post_templates VALUES(5,'Storytelling Post','linkedin_post','Persönliche Geschichte mit Lerneffekt. Emotionaler als andere Formate, baut Vertrauen auf. Ideal für warme Zielgruppen (MoFu).',unistr('Hook (emotional / neugierig)\u000aAusgangssituation / Problem\u000aWendepunkt (Erkenntnis)\u000aLösung / Learnings\u000aCTA'),'Letzte Woche saß ich mit einem CEO zusammen, der nicht wusste, wo seine Deals gerade stehen. Wir haben in 2 Stunden seine Pipeline aufgeräumt. Ergebnis: 30% mehr Sichtbarkeit.','["B2B-1","B2B-3"]','builtin',1,'2026-09-14 10:34:20','2026-09-14 10:34:20','["mofu"]');
INSERT INTO post_templates VALUES(6,'Listicle','linkedin_post','Aufzählung mit Mehrwert, leicht konsumierbar. Funktioniert auf ToFu und MoFu — breite Zielgruppe, niedrige Einstiegshürde.',unistr('Hook (Zahl + Thema)\u000aPunkt 1\u000aPunkt 2\u000aPunkt 3\u000aBonus / Fazit\u000aCTA'),'5 Dinge, die wir von unseren besten Kunden über CRM gelernt haben: 1. Sie pflegen Daten täglich. 2. Sie haben Property-Regeln. 3. Sie forecasten konservativ. 4. Sie reviewen wöchentlich. 5. Sie haben einen Plan B.','["B2B-1","B2B-2","B2B-3"]','builtin',1,'2026-09-14 10:34:20','2026-09-14 10:34:20','["tofu","mofu"]');
INSERT INTO post_templates VALUES(7,'Question Post','linkedin_post','Frage ans Netzwerk — hohe Engagement-Rate. Erzeugt Sichtbarkeit durch Kommentare. Klassisches ToFu-Format.',unistr('Frage (provokant / neugierig)\u000aKontext (warum die Frage)\u000aEigene Einschätzung\u000aDiskussionsaufforderung'),'Warum haben die meisten Unternehmen kein Pipeline-Review? Weil es weh tut, die Wahrheit zu sehen. Aber genau das ist der erste Schritt zur Besserung. Wie haltet ihr es?','["B2B-1","B2B-2","B2B-3"]','builtin',1,'2026-09-14 10:34:20','2026-09-14 10:34:20','["tofu"]');
INSERT INTO post_templates VALUES(8,'Ad Copy — Schmerz','ad_copy','Pain-Frame: zeigt das Problem, bietet Ausweg. Stark für ToFu/MoFu-Ads, wenn der Schmerz bekannt ist.',unistr('Primary Text (max 125 Zeichen)\u000aHeadline (max 40 Zeichen)\u000aDescription\u000aCTA'),'Primary: Forecast daneben? Vielleicht liegt es nicht am Vertrieb. Headline: Kostenloses Pipeline-Audit','["B2B-2","B2B-3"]','builtin',1,'2026-09-14 10:34:20','2026-09-14 10:34:20','["tofu","mofu"]');
INSERT INTO post_templates VALUES(9,'Ad Copy — Gain','ad_copy','Gain-Frame: zeigt den Outcome. Besser für warme Zielgruppen (MoFu/BoFu), die schon wissen, was sie wollen.',unistr('Primary Text (max 125 Zeichen)\u000aHeadline (max 40 Zeichen)\u000aDescription\u000aCTA'),'Primary: Planbares Wachstum beginnt mit einem sauberen CRM. Headline: Zur kostenlosen Demo','["B2B-1","B2B-2"]','builtin',1,'2026-09-14 10:34:20','2026-09-14 10:34:20','["mofu","bofu"]');
INSERT INTO post_templates VALUES(10,'Newsletter — Akquise','newsletter','Für neue Abonnenten / Lead-Generierung. Überzeugend, Problem-fokussiert. Ziel: Klick auf den CTA.',unistr('Betreff (max 50 Zeichen, Neugier wecken)\u000aPreview-Text (Ergänzung, max 90 Zeichen)\u000aEinstieg: Problem / Thesen-Eröffnung\u000aHauptteil: Problem → Lösung → Beweis\u000aCTA (ein klarer Link)'),'Betreff: Warum 60% der Forecasts falsch sind','["B2B-1","B2B-2","B2B-3"]','builtin',1,'2026-09-14 10:34:20','2026-09-14 10:34:20','["tofu","mofu"]');
INSERT INTO post_templates VALUES(11,'Newsletter — Bestandskunden','newsletter','Für bestehende Kunden / warme Kontakte. Persönlich, nah, konkret. Weniger Überzeugung, mehr Mehrwert und Bindung.',unistr('Betreff (persönlich, max 50 Zeichen)\u000aEinleitung (persönliche Ansprache, 1-2 Sätze)\u000aHauptteil (1-2 konkrete, umsetzbare Punkte)\u000aNext Step (Handlungsaufforderung, nicht verkäuferisch)\u000aSign-off'),'Betreff: Datenhygiene in 15 Minuten — diese Woche','["B2B-1","B2B-2","B2B-3"]','builtin',1,'2026-09-14 10:34:20','2026-09-14 10:34:20','["mofu","bofu"]');
INSERT INTO post_templates VALUES(12,'Landing Page Headline','landing_page_headlines','Konversionsfokus, kein Storytelling. Klassisches BoFu-Element: Besucher kennen das Problem, entscheiden sich gerade.',unistr('Hero Headline (max 20 Wörter)\u000aSub-Headline (max 30 Wörter)\u000a3 Bullet Points (je 1 Zeile)\u000aCTA-Button-Text (2-4 Wörter)'),'Headline: Schluss mit Blindflug im Forecast','["B2B-1","B2B-2"]','builtin',1,'2026-09-14 10:34:20','2026-09-14 10:34:20','["bofu"]');
INSERT INTO content_items VALUES('CNT-24079C',1,'ANG-AD19D8','post','linkedin_post','Systemgetrieben Vertrieb & Service ohne Personenabhängigkeit − Angebotszeit CPQ ',unistr('In einer dynamischen Geschäftswelt ist ein systemgetriebener Vertrieb und Service entscheidend, um unabhängig von einzelnen Personen erfolgreich zu sein. 🌐 Mit der Integration von CPQ in HubSpot optimieren wir die Angebotszeit und schaffen einen nahtlosen Workflow. 🚀\u000a\u000aUnsere Auto-Support-Lösung, Breeze AI, klassifiziert und beantwortet Anfragen blitzschnell, was die Effizienz erheblich steigert. Gerade in der Industrie-IT ist ein zentrales CRM essenziell, um den Überblick zu behalten und Abhängigkeiten zu minimieren.\u000a\u000aSetzen Sie auf ein starkes System, das Ihren Vertrieb auf das nächste Level hebtkonkret\u000a\u000a#viscale #Vertriebssystem #HubSpot #Mittelstand'),'in_produktion','viscale',NULL,NULL,'B2B-3','E3-02 · Vertrieb hängt an Personen','Direkt','2026-09-08 11:21:38','2026-09-08 11:21:38',NULL,'contrarian',NULL,NULL,NULL);
INSERT INTO content_items VALUES('CNT-842F96',1,'ANG-EB704C','post','linkedin_post','Ein sauberes CRM-System ist das Fundament für planbares Wachstum und effiziente ',unistr('🔍 Ein sauberes CRM-System: Der Schlüssel zu planbarem Wachstum und effizienten Prozessenkonkret 🔑\u000a\u000aUnternehmen, die in einem Datenchaos versinken, verlieren wertvolle Zeit und Ressourcen. Ein gepflegtes CRM ist das Fundament, auf dem strategische Vertriebsentscheidungen getroffen und nachhaltiges Wachstum geplant werden können.\u000a\u000aMit einem strukturierten CRM-System wie HubSpot schaffen Sie Ordnung in Ihrem Datenbestand und setzen den Fokus auf das Wesentliche: Ihre Kunden. 🚀\u000a\u000aErgreifen Sie die Chance, Datenhygiene in den Mittelpunkt zu stellen und erleben Sie, wie Effizienz und Wachstum Hand in Hand gehenkonkret\u000a\u000a#viscale #Vertriebssystem #HubSpot #Mittelstand'),'in_produktion','viscale',NULL,NULL,'B2B-1','E3-06 · Datenchaos & fehlende Datenhygiene','Vision','2026-09-08 11:23:36','2026-09-08 11:23:36',NULL,'story',NULL,NULL,NULL);
INSERT INTO content_items VALUES('CNT-36BE3F',1,'ANG-E0A602','post','linkedin_post','Vertrieb hängt oft an Personen statt an Prozessen – wir schaffen ein System, das','In vielen Unternehmen hängt der Vertriebserfolg stark an einzelnen Personen, was zu potenziellen Risiken und Abhängigkeiten führt. Bei uns steht die Entwicklung eines robusten Vertriebssystems im Vordergrund, das unabhängig von Einzelpersonen agiert und nachhaltig Ergebnisse liefert. Unsere Lösung sorgt für einen strukturierten, effizienten Prozess, der den Vertrieb auf das nächste Level hebt. #viscale #Vertriebssystem #HubSpot #Mittelstand','in_produktion','viscale',NULL,NULL,'B2B-1','E3-02 · Vertrieb hängt an Personen','Drastisch','2026-09-08 12:28:19','2026-09-08 12:28:19',NULL,'story',NULL,NULL,NULL);
INSERT INTO content_items VALUES('CNT-A6C2B6',1,'ANG-E0A602','post','linkedin_post','Vertrieb hängt oft an Personen statt an Prozessen – wir schaffen ein System, das',unistr('**LinkedIn-Post:**\u000a\u000aIn vielen Unternehmen hängt der Vertriebserfolg stark von einzelnen Personen ab, was potenzielle Risiken und Abhängigkeiten mit sich bringt. Wenn ein unverzichtbarer Vertriebsmitarbeiter das Unternehmen verlässt, kann dies erhebliche Auswirkungen auf die Umsatzzahlen haben. Unsere Mission ist es, ein robustes Vertriebssystem zu entwickeln, das unabhängig von Einzelpersonen funktioniert und nachhaltige Ergebnisse liefert. Ein solches System reduziert nicht nur die Abhängigkeit von spezifischen Mitarbeitern, sondern ermöglicht es auch, die Vertriebsstrategie auf eine breitere Basis zu stellen.\u000a\u000aMit unserer Lösung schaffen wir einen strukturierten und effizienten Prozess, der den Vertrieb auf das nächste Level hebt. Wir setzen auf moderne Technologien und bewährte Methoden, um einen nahtlosen und skalierbaren Vertriebsprozess zu etablieren. Ein zentrales Element unserer Strategie ist die Implementierung von HubSpot, einer Plattform, die es ermöglicht, alle Vertriebsaktivitäten zentral zu steuern und zu analysieren. HubSpot bietet umfassende CRM-Funktionen, die es den Vertriebsmitarbeitern erleichtern, Kundenbeziehungen zu pflegen und auszubauen. Durch die Automatisierung von Routineaufgaben können sich die Mitarbeiter auf das Wesentliche konzentrieren: den Aufbau und die Pflege langfristiger Kundenbeziehungen.\u000a\u000aDarüber hinaus legen wir großen Wert auf die Schulung und Entwicklung der Vertriebsmitarbeiter. Ein gut ausgebildetes Team ist der Schlüssel zu einem erfolgreichen Vertriebssystem. Unsere Schulungsprogramme sind darauf ausgelegt, die Fähigkeiten und das Wissen der Mitarbeiter kontinuierlich zu erweitern und an die sich ständig ändernden Marktanforderungen anzupassen. Dies ermöglicht es den Vertriebsmitarbeitern, nicht nur ihre individuellen Ziele zu erreichen, sondern auch zum Gesamterfolg des Unternehmens beizutragen.\u000a\u000aEin weiterer wichtiger Aspekt unserer Lösung ist die Datenanalyse. In der heutigen datengetriebenen Welt ist es unerlässlich, fundierte Entscheidungen auf Basis von Daten zu treffen. Wir bieten Tools und Methoden an, die es ermöglichen, Vertriebsdaten zu sammeln, zu analysieren und in umsetzbare Strategien zu übersetzen. Dadurch können Unternehmen Trends erkennen, Chancen identifizieren und potenzielle Risiken frühzeitig abwenden.\u000a\u000aUnsere Lösung richtet sich insbesondere an mittelständische Unternehmen, die oft nicht über die Ressourcen verfügen, um komplexe Vertriebssysteme zu entwickeln. Wir bieten eine maßgeschneiderte Lösung, die den spezifischen Bedürfnissen und Herausforderungen des Mittelstands gerecht wird. Unser Ziel ist es, den Unternehmen zu helfen, ihr volles Potenzial auszuschöpfen und in einem zunehmend wettbewerbsintensiven Marktumfeld erfolgreich zu sein.\u000a\u000aDie Implementierung eines robusten Vertriebssystems ist ein fortlaufender Prozess, der kontinuierliche Anpassungen und Optimierungen erfordert. Wir begleiten unsere Kunden auf diesem Weg und bieten umfassende Unterstützung in jeder Phase der Implementierung und darüber hinaus. Unser Team von Experten steht bereit, um Fragen zu beantworten, Herausforderungen zu meistern und sicherzustellen, dass das Vertriebssystem reibungslos funktioniert und die gewünschten Ergebnisse liefert.\u000a\u000aWir sind stolz darauf, Unternehmen dabei zu helfen, ihre Vertriebsprozesse zu transformieren und zu optimieren. Unsere bewährten Methoden und innovativen Lösungen haben bereits vielen Unternehmen geholfen, ihre Umsätze zu steigern, ihre Effizienz zu verbessern und ihre Marktposition zu stärken. Der Erfolg unserer Kunden ist unser Erfolg, und wir sind bestrebt, langfristige Partnerschaften aufzubauen, die auf Vertrauen und gemeinsamen Zielen basieren.\u000a\u000aIn einer sich schnell verändernden Geschäftswelt ist es wichtiger denn je, agil und anpassungsfähig zu sein. Ein starkes Vertriebssystem bietet die Flexibilität, schnell auf Veränderungen zu reagieren und neue Marktchancen zu nutzen. Es ermöglicht Unternehmen, nicht nur auf Herausforderungen zu reagieren, sondern proaktiv zu handeln und ihre Zukunft selbst in die Hand zu nehmen.\u000a\u000aWenn auch Sie Ihren Vertrieb auf das nächste Level heben möchten, setzen Sie sich mit uns in Verbindung. Lassen Sie uns gemeinsam die Zukunft Ihres Unternehmens gestalten und sicherstellen, dass Sie für die Herausforderungen von morgen bestens gerüstet sind. #viscale #Vertriebssystem #HubSpot #Mittelstand #Vertriebsoptimierung #Kundenerfolg #Datenanalyse #CRM #Vertriebsstrategie #Vertriebstransformation #Innovation #Wachstum #Agilität #Effizienz #Kundenbeziehungen #Marktposition #Vertriebsteam #Vertriebsprozess #Vertriebsautomatisierung #Vertriebsentwicklung #Unternehmenswachstum #Vertriebsunterstützung #Partnerschaft #Erfolg #Vertriebsinnovationen #Vertriebsherausforderungen #Vertriebschancen #Vertriebszukunft #Vertriebsstärke #Vertriebspotenzial #Vertriebsflexibilität #Vertriebsagilität #Vertriebsanpassung #Vertriebsstrategieentwicklung #Vertriebsimplementierung #Vertriebsbegleitung #Vertriebsberatung #Vertriebsoptimierungspartner'),'geplant','viscale',NULL,NULL,'B2B-1','E3-02 · Vertrieb hängt an Personen','Drastisch','2026-09-08 13:12:10','2026-09-10 14:47:20',NULL,'contrarian',NULL,NULL,NULL);
