INSERT INTO sources VALUES('SRC-761266',1,'https://www.linkedin.com/posts/julius-mannal_i-aeo-graded-my-orgs-website-why-because-activity-7450442000996200448-GQ0T?utm_source=share&utm_medium=member_desktop&rcm=ACoAAARCghMBy107mVg4He4dZZcCiE_wlOLc9fk','url','intern','https://www.linkedin.com/posts/julius-mannal_i-aeo-graded-my-orgs-website-why-because-activity-7450442000996200448-GQ0T?utm_source=share&utm_medium=member_desktop&rcm=ACoAAARCghMBy107mVg4He4dZZcCiE_wlOLc9fk','quick-20260915','2026-09-15 11:06:31','2026-09-15 11:06:31','https://www.linkedin.com/posts/julius-mannal_i-aeo-graded-my-orgs-website-why-because-activity-7450442000996200448-GQ0T?utm_source=share&utm_medium=member_desktop&rcm=ACoAAARCghMBy107mVg4He4dZZcCiE_wlOLc9fk',0,'weekly',NULL,NULL,NULL,'https://www.linkedin.com/posts/julius-mannal_i-aeo-graded-my-orgs-website-why-because-activity-7450442000996200448-GQ0T?utm_source=share&utm_medium=member_desktop&rcm=ACoAAARCghMBy107mVg4He4dZZcCiE_wlOLc9fk',NULL);
INSERT INTO sources VALUES('SRC-7678FE',1,unistr('I AEO graded my org''s website.\u000a\u000aWhy?\u000a\u000aBecause 60% of web searches now end withou...'),'research','intern',NULL,'quick-20260915','2026-09-15 11:06:47','2026-09-15 11:06:47',NULL,0,'weekly',NULL,NULL,NULL,unistr('I AEO graded my org''s website.\u000a\u000aWhy?\u000a\u000aBecause 60% of web searches now end without a single click.\u000a\u000aUsers get their answer directly from Google''s AI Overview, ChatGPT, or Perplexity — and never visit your site.\u000a\u000aAnd here''s what makes this even more urgent:\u000a\u000a40% of consumers already trust Gen AI search results MORE than traditional organic results.\u000a66% act on AI-generated content without ever verifying it elsewhere.\u000a\u000aThat means if an LLM recommends you → you win the deal before the competitor even gets a click. \u000a\u000aAnd if it doesn''t → you''re invisible to the buyer before the conversation even starts.\u000a\u000aThat''s why AEO isn''t a "nice to have" anymore. It''s the new SEO.\u000a\u000aCurious how your website performs in the eyes of AI engines?\u000aComment AEO below — and I''ll grade your website for free. 👇'),NULL);
INSERT INTO sources VALUES('SRC-9881D9',1,'AEO Feature HubSpot','research','intern',NULL,'quick-20260915','2026-09-15 12:54:17','2026-09-15 12:54:17',NULL,0,'weekly',NULL,NULL,NULL,unistr('I AEO graded my org''s website.\u000a\u000aWhy?\u000a\u000aBecause 60% of web searches now end without a single click.\u000a\u000aUsers get their answer directly from Google''s AI Overview, ChatGPT, or Perplexity — and never visit your site.\u000a\u000aAnd here''s what makes this even more urgent:\u000a\u000a40% of consumers already trust Gen AI search results MORE than traditional organic results.\u000a66% act on AI-generated content without ever verifying it elsewhere.\u000a\u000aThat means if an LLM recommends you → you win the deal before the competitor even gets a click. \u000a\u000aAnd if it doesn''t → you''re invisible to the buyer before the conversation even starts.\u000a\u000aThat''s why AEO isn''t a "nice to have" anymore. It''s the new SEO.\u000a\u000aCurious how your website performs in the eyes of AI engines?\u000aComment AEO below — and I''ll grade your website for free. 👇'),NULL);
INSERT INTO sources VALUES('SRC-F015A8',3,unistr('Säule 1 – Governance & Souveränität\u000aSelf-Governance statt Verbot: Regeln, die Mi...'),'research','intern',NULL,'quick-20260924','2026-09-24 13:47:27','2026-09-24 13:47:27',NULL,0,'weekly',NULL,NULL,NULL,unistr('Säule 1 – Governance & Souveränität\u000aSelf-Governance statt Verbot: Regeln, die Mitarbeitende tatsächlich befolgen\u000aSchatten-KI: Laut ZEW verbieten nur 4 % bzw. 8 % der Firmen ihrer Belegschaft KI-Nutzung, die große Mehrheit erlaubt sie, steuert sie aber kaum → „Erlauben ≠ befähigen“ Skill-Sprinters\u000aEin Interface für alle statt 12 Privat-Accounts\u000aLock-in: Prompts, Skills, Wissensbasen = Firmenvermögen, nicht Anbietereigentum\u000aAI Act nüchtern: Art. 50 seit 2. Aug. – was KMUs wirklich tun müssen (wenig, aber das Richtige)\u000aSäule 2 – Kosten & Transparenz\u000aBitkom: 33 % sagen, KI ist teurer als geplant → woher Kosten kommen (Token, Tool-Wildwuchs, Doppellizenzen) MyBusinessFuture\u000a„Was kostet ein KI-Arbeitsplatz wirklich?“ – eigene Zahlen offenlegen\u000aModell-Routing: nicht jede Frage braucht das teuerste Modell\u000aWer sieht, was die KI tut? Logs, Nachvollziehbarkeit\u000aSäule 3 – Prozesse vor Tools\u000aThese: KI ohne Prozess = schnelleres Chaos\u000aAgenten brauchen dokumentierte Abläufe, sonst nichts zu automatisieren\u000a„Welche Marge basiert darauf, dass etwas schwer ist, das gerade leicht wird?“\u000aFachkräftemangel: KI als Wachstumsoption, nicht Stellenabbau\u000aSäule 4 – Anti-FOMO / Realitätscheck\u000a„Du verpasst keinen Zug“ – n8n-Spaghetti vs. was im Alltag läuft\u000aModelldiskussion: Modelle austauschbar, Kontext nicht\u000aDemo ≠ Betrieb: was passiert, wenn der Provider 2h weg ist?\u000aHype-Post seziert: „Claude hat alles digitalisiert“ – was fehlt (Rechte, Daten, Wartung)\u000aSäule 5 – Einordnung: Wo stehen KMUs?\u000aZahlen widersprechen sich: ifo: 54,5 % nutzen KI (Mai 2026), Mittelstand nur 47,2 %, sogar hinter kleinen Firmen; KfW: klassischer Mittelstand rund 20 % → Post: „Warum jede Studie was anderes sagt“ Skill-SprintersAndersAI\u000aRealität meist: Chat-Fenster, Einzelnutzung, keine Orchestrierung\u000aReifegrad-Stufen als Serie: Chat → Team-Workspace → Wissensbasis → Workflows → Agenten\u000aGrößte Hürde: 53 % fehlende Kompetenz → Schulung > Tool Skill-Sprinters\u000aSäule 6 – Behind the Scenes viminds\u000aEigener Stack erklärt (ohne Tech-Jargon)\u000aFehler/Learnings: was nicht funktioniert hat\u000aKI-Richtlinie: wie formuliert, damit Leute melden statt verstecken\u000aAI-Act-Schulung: Aufbau, Quiz, Erfahrungen\u000aWeitere KMU-Fragen (Content-Futter)\u000aDatenschutz: darf Kundendaten rein?\u000aWer ist intern verantwortlich?\u000aChatGPT Team vs. Copilot vs. eigene Lösung?\u000aWie Produktivität messen?\u000aWas sagt der Betriebsrat/Team?\u000aQualität: wer prüft Output?\u000aFormate\u000aMythos vs. Realität\u000a1 These + 3 Sätze Begründung\u000aCheckliste (PDF-Karussell)\u000aVorher/Nachher aus eigenem Betrieb\u000aMonatlicher „Zahlen-Realitätscheck“'),NULL);
